"""Bezpečnost: hlavičky a CSP, příznaky cookie, CSRF, hesla (čistá i hashovaná), přihlášení podle IP, náhledová adresa,
chybná konfigurace, XSS, přímý přístup ke sdíleným souborům. Spouští se s prostředím `tests/env.sh up demo`."""
from lhtest import *
import gzip
T = Tests('Bezpečnost')
T.section('Hlavičky a vykreslená stránka')
c = Client('full'); t = c.get(); h = c.resp_headers
csp = h.get('Content-Security-Policy', '')
script_src = re.search(r"script-src ([^;]*)", csp).group(1) if re.search(r"script-src ([^;]*)", csp) else ''
T.check("CSP: skripty jen z vlastních souborů nebo s nonce, bez 'unsafe-inline' a 'unsafe-eval'", "'self'" in script_src and 'nonce-' in script_src and 'unsafe' not in script_src, csp)
T.check("CSP: frame-ancestors 'none', form-action 'self', object-src 'none', base-uri 'self', žádné externí zdroje", all(x in csp for x in ("frame-ancestors 'none'", "form-action 'self'", "object-src 'none'", "base-uri 'self'")) and 'http' not in csp, csp)
T.check('další hlavičky: X-Frame-Options DENY, nosniff, Referrer-Policy, Permissions-Policy', h.get('X-Frame-Options') == 'DENY' and h.get('X-Content-Type-Options') == 'nosniff' and h.get('Referrer-Policy') == 'same-origin' and 'camera=()' in h.get('Permissions-Policy', ''))
nonce = re.search(r"nonce-([A-Za-z0-9+/=]+)", csp).group(1)
tags = re.findall(r'<script([^>]*)>', t)
T.check('každý inline skript má nonce shodný s hlavičkou (%d inline skriptů)' % len([x for x in tags if 'src=' not in x]), all(('nonce="%s"' % nonce in x) for x in tags if 'src=' not in x))
c2 = Client('full'); c2.get(); T.check('nonce je pro každý požadavek jiný', re.search(r"nonce-([A-Za-z0-9+/=]+)", c2.resp_headers.get('Content-Security-Policy', '')).group(1) != nonce)
T.check('stránka nemá inline obsluhy událostí (onclick, onsubmit, …) ani odkazy na CDN či cizí domény', not re.search(r'\son(submit|click|change|input|keyup|load|error)="', t) and not re.search(r'(src|href)="https?://', t))
forms = re.findall(r'<form\b[^>]*method="POST"[^>]*>(.{0,160})', t, re.I | re.S)
T.check('každý formulář POST nese skrytý token CSRF (%d formulářů)' % len(forms), len(forms) >= 1 and all('name="lh_csrf"' in f for f in forms))
sc = c.resp_headers.get_all('Set-Cookie') or []; sess = [x for x in sc if x.startswith('PHPSESSID')]
T.check('cookie relace: HttpOnly a SameSite=Lax, po HTTP bez příznaku Secure', sess and 'HttpOnly' in sess[0] and 'SameSite=Lax' in sess[0] and 'secure' not in sess[0].lower(), sess)
s3 = Client('full', headers={'X-Forwarded-Proto': 'https'}); s3.get(); sess3 = [x for x in (s3.resp_headers.get_all('Set-Cookie') or []) if x.startswith('PHPSESSID')]
T.check('cookie relace dostane Secure, když proxy hlásí HTTPS (X-Forwarded-Proto)', sess3 and 'secure' in sess3[0].lower(), sess3)
T.section('Ochrana proti CSRF')
adm = Client('full', admin=True); old = setting('collect_disabled') or '0'
adm.post({'action': 'set_collection', 'collect': 'off'}, csrf=False); fl = adm.flash()
T.check('POST bez tokenu je odmítnut a nic se nezmění', fl[0] == 'danger' and 'bezpečnostní token' in fl[1] and setting('collect_disabled') in ('', '0'), fl)
adm.post({'action': 'set_collection', 'collect': 'off'}, csrf='0' * 64); fl = adm.flash()
T.check('POST se špatným tokenem je odmítnut', 'bezpečnostní token' in fl[1] and setting('collect_disabled') in ('', '0'))
other = Client('full', admin=True); other.get()
adm.post({'action': 'set_collection', 'collect': 'off'}, csrf=other.csrf); fl = adm.flash()
T.check('token z cizí relace nestačí (je vázaný na relaci)', 'bezpečnostní token' in fl[1] and setting('collect_disabled') in ('', '0'))
adm.get(); adm.post({'action': 'set_collection', 'collect': 'off'}); T.check('POST s platným tokenem projde', setting('collect_disabled') == '1', adm.flash())
adm.post({'action': 'set_collection', 'collect': 'on'}); T.check('a zase se dá vrátit', setting('collect_disabled') == '0')
anon = Client('full'); anon.get(); n0 = q("select count(*) from toilet_reports"); now = dt.datetime.now().strftime('%Y-%m-%dT%H:%M')
anon.post({'action': 'report', 'reporter': 'CSRF', 'cubicle': 'prava', 'status': 'ok', 'reported_at': now}, csrf=False)
T.check('veřejné hlášení bez tokenu se neuloží', q("select count(*) from toilet_reports") == n0)
anon.post({'action': 'report', 'reporter': 'CSRF', 'cubicle': 'prava', 'status': 'ok', 'reported_at': now})
T.check('s tokenem se uloží', int(q("select count(*) from toilet_reports")) == int(n0) + 1)
T.section('Volání domácího serveru (záloha, souhrn) s klíčem se CSRF netýká')
def raw_post(action, token):
    r = urllib.request.Request('http://127.0.0.1:8081/', data=urllib.parse.urlencode({'action': action}).encode(), headers={'X-Backup-Token': token, 'X-Lh-Proxy': 'PROXYSECRET123'})
    try: return urllib.request.urlopen(r).read()
    except urllib.error.HTTPError as e: return e.read()
b = raw_post('backup_token', 'b' * 40)
try: sql = gzip.decompress(b).decode('utf-8')
except OSError: sql = b.decode('utf-8', 'replace')
T.check('záloha se správným klíčem funguje bez tokenu CSRF', sql.rstrip().split('\n')[-1].startswith('-- KONEC ZÁLOHY'))
b2 = raw_post('backup_token', 'x' * 40); T.check('záloha se špatným klíčem se nevydá', 'KONEC ZÁLOHY'.encode() not in b2 and b'CREATE TABLE' not in b2)
q("DELETE FROM app_settings WHERE setting_key='digest_last_sent'"); d = raw_post('digest_send', 'b' * 40).decode('utf-8', 'replace')
T.check('týdenní souhrn s klíčem proběhne bez tokenu (odpověď „%s“)' % d.strip()[:40], d.startswith('OK') or d.startswith('SKIP'))
T.section('Přihlášení admina heslem (formulář v hlavičce)')
tl = Client('full').get(); T.check('anonymní návštěvník plné verze vidí formulář „Admin“ s políčkem hesla a tokenem CSRF', 'name="admin_password"' in tl and re.search(r'value="admin_login"[^>]*>\s*<input type="password"|name="lh_csrf"', tl) is not None)
T.check('přihlášený uživatel z proxy (identita) formulář nemá, náhled také ne', 'name="admin_password"' not in Client('user').get() and 'name="admin_password"' not in Client('preview').get())
set_setting('collect_disabled', '1'); lf = Client('full'); tl2 = lf.get()
T.check('i při vypnutém sběru dat je na stránce formulář s tokenem (jinak by se admin nepřihlásil)', 'name="admin_password"' in tl2 and bool(lf.csrf))
lf.post({'action': 'admin_login', 'admin_password': 'TestAdminPw1'}); T.check('přihlášení heslem přes token z té stránky funguje', 'id="pane-admin"' in lf.get())
set_setting('collect_disabled', '0')
T.section('Hesla admina')
bad = Client('full'); bad.post({'action': 'admin_login', 'admin_password': 'špatné heslo'}); fl = bad.flash()
T.check('špatné heslo: hláška a žádný přístup do administrace', fl[0] == 'danger' and 'Neplatné' in fl[1] and 'id="pane-admin"' not in bad.get())
T.check('správné čisté heslo z konfigurace funguje', 'id="pane-admin"' in Client('full', admin=True).get())
hs = Client('hashed'); hs.post({'action': 'admin_login', 'admin_password': 'HashedAdminPw1'}); T.check('hashované heslo (bcrypt z password_hash) funguje', 'id="pane-admin"' in hs.get())
hb = Client('hashed'); hb.post({'action': 'admin_login', 'admin_password': 'TestAdminPw1'}); T.check('u hashované konfigurace neprojde jiné heslo', 'id="pane-admin"' not in hb.get())
T.check('uložený hash začíná $2y$ a v konfiguraci není čisté heslo', open(os.path.join(RUN, 'site_hashed', 'lh_config.php'), encoding='utf-8').read().count('$2y$') == 1 and 'HashedAdminPw1' not in open(os.path.join(RUN, 'site_hashed', 'lh_config.php'), encoding='utf-8').read())
T.section('Přihlášení bez hesla podle IP (ve výchozím stavu vypnuté)')
old = Client('full', headers={'X-Forwarded-For': '192.0.2.50'}); old.post({'action': 'admin_login', 'admin_password': ''}); T.check('bez nastavení ip_login_ips nepustí prázdné heslo žádná IP', 'id="pane-admin"' not in old.get())
ip = Client('iplogin', headers={'X-Forwarded-For': '203.0.113.7'}); ip.post({'action': 'admin_login', 'admin_password': ''}); T.check('IP povolená v konfiguraci projde bez hesla', 'id="pane-admin"' in ip.get())
ip2 = Client('iplogin', headers={'X-Forwarded-For': '198.51.100.9'}); ip2.post({'action': 'admin_login', 'admin_password': ''}); T.check('jiná IP ne (ani s prázdným heslem)', 'id="pane-admin"' not in ip2.get())
T.section('Náhledová adresa a konfigurace')
pv = Client('preview', admin=True); fl = pv.flash(); pv.post({'action': 'set_collection', 'collect': 'off'}); T.check('na náhledové adrese nejde nic změnit ani s admin přihlášením', setting('collect_disabled') in ('', '0') and 'pouze' in (pv.flash()[1] or 'pouze') + 'pouze')
bc = Client('badconf'); t = bc.get()
T.check('neúplná konfigurace: HTTP 500 a výpis chybějících klíčů (full_hosts, device_secret)', bc.code == 500 and 'full_hosts' in t and 'device_secret' in t, t[:200])
T.section('XSS a nebezpečný vstup')
x = Client('full'); x.get(); payload = '<script>alert(1)</script> "><img src=x onerror=alert(2)>'
x.post({'action': 'report_note', 'reporter': payload, 'person_name': '', 'poznatek': payload})
adm2 = Client('full', admin=True); pg = adm2.get()
T.check('vložený HTML kód se v administraci zobrazí jen jako text', '<script>alert(1)' not in pg and '<img src=x onerror' not in pg and '&lt;script&gt;alert(1)' in pg)
sys.exit(T.finish())
